import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"A Self-Evolving Framework for Efficient Terminal Agents via Observational Context Compression","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.19572","title":"A Self-Evolving Framework for Efficient Terminal Agents via Observational Context Compression","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.19572,"authors":["Jincheng Ren","Siwei Wu","Yizhi Li","Kang Zhu","Shu Xu","Boyu Feng","Ruibin Yuan","Wei Zhang","Riza Batista-Navarro","Jian Yang","Chenghua Lin"],"domains":["cs.CL","context management"],"html":"https://arxiv.org/html/2604.19572v1","pdf_path":"pdfs/2604.19572.pdf","published_date":"2026-04-21T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-21-taco-observational-context-compression-terminal-agents-2604-19572.md","filePath":"research/papers/2026-04-21-taco-observational-context-compression-terminal-agents-2604-19572.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-21-taco-observational-context-compression-terminal-agents-2604-19572.md"};function i(s,e,l,c,m,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="a-self-evolving-framework-for-efficient-terminal-agents-via-observational-context-compression" tabindex="-1">A Self-Evolving Framework for Efficient Terminal Agents via Observational Context Compression <a class="header-anchor" href="#a-self-evolving-framework-for-efficient-terminal-agents-via-observational-context-compression" aria-label="Permalink to &quot;A Self-Evolving Framework for Efficient Terminal Agents via Observational Context Compression&quot;">​</a></h1><p><strong>Authors</strong>: Jincheng Ren, Siwei Wu, Yizhi Li, Kang Zhu, Shu Xu, Boyu Feng, Ruibin Yuan, Wei Zhang, Riza Batista-Navarro, Jian Yang, Chenghua Lin <strong>Published</strong>: April 21, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.19572" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.19572</a> · <a href="https://arxiv.org/html/2604.19572v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.19572 <strong>Categories</strong>: cs.CL, context management <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.19572" target="_blank" rel="noreferrer">research/papers/pdfs/2604.19572.pdf</a> (27 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>As terminal agents scale to long-horizon, multi-turn workflows, a key bottleneck is not merely limited context length, but the accumulation of noisy terminal observations in the interaction history. Retaining raw observations preserves useful environment feedback, but also leads to context saturation and high token cost; conversely, naive compression may discard task-critical signals needed for subsequent actions. Because terminal environments are highly heterogeneous across repositories, commands, and execution states, heuristic-based or fixed-prompt compression methods are difficult to generalize. We propose TACO, a plug-and-play, training-free, self-evolving Terminal Agent Compression framework for existing terminal agents. TACO automatically discovers, refines, and reuses structured compression rules from interaction trajectories, enabling workflow-adaptive filtering of low-value terminal outputs while preserving task-relevant observations. Experiments on TerminalBench (TB 1.0 and TB 2.0) and four additional terminal-related benchmarks, including SWE-Bench Lite, CompileBench, DevEval, and CRUST-Bench, show that TACO consistently improves task performance and token efficiency across agent scaffolds and backbone models. On TerminalBench, TACO yields 1%-4% accuracy gains across strong agentic models and improves accuracy by around 2%-3% under the same token budget. On additional terminal-related benchmarks, it reduces total token consumption while maintaining or improving task success rates. These results suggest that self-evolving, workflow-adaptive observation compression is an effective path toward more reliable and efficient long-horizon terminal agents. The code is publicly available at <a href="https://github.com/multimodal-art-projection/TACO" target="_blank" rel="noreferrer">https://github.com/multimodal-art-projection/TACO</a>.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>TACO</strong>（Terminal Agent Compression framework）：plug-and-play、training-free、self-evolving 的 observation 壓縮框架，可掛接現有 terminal agent 而無需重新訓練。</li><li>核心機制：從 interaction trajectory 自動<strong>發現、精化、重用</strong> structured compression rules，達到 workflow-adaptive 的低價值 terminal output 過濾，同時保留 task-critical observations。</li><li>解決 terminal 環境高度異質性（不同 repo、command、execution state）導致 heuristic / fixed-prompt 壓縮方法難以泛化的問題。</li><li>在六個 benchmark（TerminalBench TB 1.0/2.0、SWE-Bench Lite、CompileBench、DevEval、CRUST-Bench）上驗證跨 agent scaffold 與 backbone model 的一致性提升。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li><strong>TerminalBench</strong>：accuracy +1%–4%（strong agentic models）；相同 token budget 下準確率提升約 2%–3%。</li><li><strong>其他四個 terminal-related benchmarks</strong>：在維持或提升 task success rate 的前提下，降低 total token consumption。</li><li>結果顯示 self-evolving、workflow-adaptive observation compression 是長 horizon terminal agent 提升可靠性與效率的有效路徑。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未列明確 limitation 章節。</li><li>潛在弱點判斷：(1) self-evolving rule discovery 依賴足夠的 trajectory 資料，cold-start 場景效果未知；(2) compression rules 的品質上限受 backbone model 推理能力限制，弱模型可能產生劣質規則；(3) 實驗僅覆蓋 terminal/code agent 場景，對 browser agent 或其他工具型 agent 的泛化性未驗證。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>Context management / NLAH 原則</strong>：TACO 的核心問題（context saturation vs. 壓縮遺失 task-critical signal）直接對應 <code>context-management.md</code> 中「Right context &gt; more context」的 NLAH 原則；TACO 的 workflow-adaptive filtering 是此原則在 agent 軌跡層的具體實現。</li><li><strong>The Loop RECORD 階段 / 自我演化迴圈</strong>：TACO 的 self-evolving rule refinement 與 <code>core.md</code> RECORD 階段「task 失敗 → 結構化反思 → 下次同類任務注入」高度同構，可視為該迴圈在 observation compression 層的 automated 版本；⚠️ TACO 屬訓練外 trajectory 挖掘，workspace 的 self-evolution 目前依賴人工 LESSONS.md 更新，自動化程度仍有落差。</li><li><strong>unverified_success 閘門 / <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）</strong>：TACO 壓縮後保留「task-relevant observations」的判準問題，對應 <code>core.md</code> TEST 階段的 <code>unverified_success</code> 閘門——壓縮結果本身是中間態，需確定性驗證才能信任；⚠️ 本庫 <code>core.md §PROPOSE 委派</code> 目前無自動化 observation 壓縮機制，落地需額外工程。</li><li><strong>Token budget / memory-compactor</strong>：TACO 減少 token consumption 的實驗結果與 <code>context-management.md</code> token budget 軟性管控（per-task ~4,000 / per-session ~30,000）直接相關；⚠️ workspace 的 <code>memory-compactor</code> skill 處理的是跨 session memory 整合，與 TACO 的 intra-session observation 壓縮屬不同層次，概念可互補但不直接等同。</li></ul>',16)])])}const h=a(n,[["render",i]]);export{u as __pageData,h as default};
